package vn.hoangminh.erp.Ht3DieuPhoi.domain;
import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.time.LocalDateTime;
@Entity @Table(name="ChuyenVan") @Getter @Setter public class ChuyenVan { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="MaChuyen") private Integer maChuyen; @Column(name="MaNguoiLap",length=20) private String maNguoiLap; @Column(name="MaTaiXe",length=20) private String maTaiXe; @Column(name="MaPhuongTien") private Integer maPhuongTien; @Column(name="MaDonHang",length=10) private String maDonHang; @Column(name="NgayKhoiHanh") private LocalDateTime ngayKhoiHanh; @Column(name="ThoiGianDuKien") private LocalDateTime thoiGianDuKien; @Column(name="ThoiGianThucTe") private LocalDateTime thoiGianThucTe; @Column(name="TrangThai",length=30) private String trangThai; }
